UPDATE "plots" p SET "country_a3" = a."a3"
FROM "valleys" v, "atlas" a
WHERE p."valley_id" = v."id"
  AND v."planet_id" = 0
  AND p."earth_cell" BETWEEN a."lo" AND a."hi";--> statement-breakpoint
-- FAIL LOUD, AND SAY WHICH ROW. An Earth plot whose cell is in no run means the
-- stored address is not a claimable cell — i.e. `plots.earth_cell` and the Earth
-- data have already diverged, which is precisely the condition a deed must never be
-- built on top of. Stopping here leaves the database exactly as it was.
DO $$
DECLARE
  n bigint;
  detail text;
BEGIN
  SELECT count(*), string_agg(format('site %s tile %s,%s cell %s', v."site_id", p."x", p."y", p."earth_cell"), '; ')
    INTO n, detail
    FROM "plots" p JOIN "valleys" v ON v."id" = p."valley_id"
    WHERE v."planet_id" = 0 AND p."country_a3" IS NULL;
  IF n > 0 THEN
    RAISE EXCEPTION 'country backfill left % Earth plot(s) with no sovereign: %', n, detail
      USING HINT = 'each row stores an earth_cell that is not a claimable cell of the '
                   'checked-in 0.5 degree mask + country index, so the address and the Earth '
                   'data have diverged. Resolve the row (or ship the matching mask), then re-run.';
  END IF;
END $$;--> statement-breakpoint
-- Everything left is on a body this atlas does not describe (there are no such
-- rows today: nothing writes planet_id <> 0 yet). The sentinel says "no sovereign
-- here", which is the truth, rather than borrowing an Earth country.
UPDATE "plots" SET "country_a3" = 'ZZZ' WHERE "country_a3" IS NULL;--> statement-breakpoint
-- A plot cannot exist without the country a deed would name, in the only layer
-- that can actually refuse one.
ALTER TABLE "plots" ALTER COLUMN "country_a3" SET NOT NULL;--> statement-breakpoint
-- The shape. An ADM0_A3 is three uppercase letters and so is the sentinel; a
-- lowercase, padded or truncated write would otherwise reach a deed as a silently
-- MISSING Country trait, which is the failure mode hardest to notice.
ALTER TABLE "plots" ADD CONSTRAINT "plots_country_a3_shape" CHECK ("plots"."country_a3" ~ '^[A-Z]{3}$');
